def solve(application_logs_raw):
    rows = []
    # collect() brings the table's rows back to Python; each command is in row.value.
    for row in application_logs_raw.collect():
        words = row.value.split(" ")
        # Work out the script, the name, the master, the shuffle partitions and the argument count.
    # spark.createDataFrame builds a DataFrame from a list of Python tuples, with these columns and types.
    return spark.createDataFrame(rows, "script STRING, app_name STRING, master STRING, shuffle_partitions STRING, args INT")
